/**
 * One-off fill for August 2026 ("09-69" style month) in the two order-report
 * sheets — generated from real BigSeller exports downloaded 2026-09-03:
 *   - Online:  "รายงาน > วิเคราะห์การขาย > รายงานคำสั่งซื้อ", date range
 *              01-31 Aug 2026, exported via the table's own download icon.
 *              The sheet had ZERO August rows before this — pure append.
 *   - Offline: "คำสั่งซื้อ" order list, กลุ่มร้านค้า = OFFLINE ALL, date range
 *              01-31 Aug 2026, exported "ส่งออกตาม SKU ร้านค้า" (SKU-level).
 *              The sheet already had SOME August rows (partial + duplicated
 *              from the dedupe issue) — this REPLACES all existing August
 *              rows with this complete, deduplicated set rather than trying
 *              to merge, per explicit instruction to rebuild August cleanly.
 *
 * Run dryRunFillAugustReports() FIRST and read the log. Only run
 * fillAugustReports() after those numbers look right. Run the offline
 * dedupe (DedupeOfflineOrders.js) BEFORE this, so the "existing August rows"
 * count reflects the deduplicated sheet, not the original duplicate-laden one.
 */
var ONLINE_SHEET_NAME = 'รายงานคำสั่งซื้อ ออนไลน์';
var OFFLINE_SHEET_NAME = 'รายงานคำสั่งซื้อ ออฟไลน์';

var THAI_MONTH_NUM_ = { 'ม.ค.': 1, 'ก.พ.': 2, 'มี.ค.': 3, 'เม.ย.': 4, 'พ.ค.': 5, 'มิ.ย.': 6, 'ก.ค.': 7, 'ส.ค.': 8, 'ก.ย.': 9, 'ต.ค.': 10, 'พ.ย.': 11, 'ธ.ค.': 12 };

function parseThaiDateYearMonth_(s) {
  if (!s) return null;
  var str = String(s).trim();
  var m = str.match(/^(\d{1,2})\s+([ก-ฮ.]+)\s+(\d{4})/);
  if (!m) return null;
  var month = THAI_MONTH_NUM_[m[2]];
  if (!month) return null;
  return { day: Number(m[1]), month: month, year: Number(m[3]) };
}

