function dryRunFillAugustReports() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var onlineSheet = ss.getSheetByName(ONLINE_SHEET_NAME);
  var offlineSheet = ss.getSheetByName(OFFLINE_SHEET_NAME);
  if (!onlineSheet) { Logger.log('Sheet not found: ' + ONLINE_SHEET_NAME); return; }
  if (!offlineSheet) { Logger.log('Sheet not found: ' + OFFLINE_SHEET_NAME); return; }

  var onlineValues = onlineSheet.getDataRange().getValues();
  var existingOnlineAugust = 0;
  for (var i = 1; i < onlineValues.length; i++) {
    var d = parseThaiDateYearMonth_(onlineValues[i][0]);
    if (d && d.year === 2026 && d.month === 8) existingOnlineAugust++;
  }

  var offlineValues = offlineSheet.getDataRange().getValues();
  var offlineHeader = offlineValues[0];
  var tsIdx = offlineHeader.indexOf('เวลาสั่งซื้อ');
  var existingOfflineAugust = 0;
  for (var j = 1; j < offlineValues.length; j++) {
    var d2 = parseThaiDateYearMonth_(offlineValues[j][tsIdx]);
    if (d2 && d2.year === 2026 && d2.month === 8) existingOfflineAugust++;
  }

  Logger.log('--- ONLINE (' + ONLINE_SHEET_NAME + ') ---');
  Logger.log('Existing August rows already in sheet: ' + existingOnlineAugust + ' (expect 0)');
  Logger.log('New rows that WOULD be appended: ' + ONLINE_AUGUST_ROWS.length);
  Logger.log('');
  Logger.log('--- OFFLINE (' + OFFLINE_SHEET_NAME + ') ---');
  Logger.log('Existing August rows that WOULD be DELETED: ' + existingOfflineAugust);
  Logger.log('New rows that WOULD be inserted after deletion: ' + OFFLINE_AUGUST_ROWS.length);
  Logger.log('');
  Logger.log('DRY RUN ONLY — no changes made. Run fillAugustReports() to apply.');
}

function fillAugustReports() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var onlineSheet = ss.getSheetByName(ONLINE_SHEET_NAME);
  var offlineSheet = ss.getSheetByName(OFFLINE_SHEET_NAME);
  if (!onlineSheet) { Logger.log('Sheet not found: ' + ONLINE_SHEET_NAME); return; }
  if (!offlineSheet) { Logger.log('Sheet not found: ' + OFFLINE_SHEET_NAME); return; }

  // --- Online: append (sheet has no August rows yet) ---
  var onlineValues = onlineSheet.getDataRange().getValues();
  for (var i = 1; i < onlineValues.length; i++) {
    var d = parseThaiDateYearMonth_(onlineValues[i][0]);
    if (d && d.year === 2026 && d.month === 8) {
      Logger.log('ABORTED: online sheet already has an August row at row ' + (i + 1) + ' — expected none. Not appending, to avoid duplicating. Investigate first.');
      return;
    }
  }
  var onlineLastRow = onlineSheet.getLastRow();
  onlineSheet.getRange(onlineLastRow + 1, 1, ONLINE_AUGUST_ROWS.length, ONLINE_AUGUST_ROWS[0].length).setValues(ONLINE_AUGUST_ROWS);
  Logger.log('Online: appended ' + ONLINE_AUGUST_ROWS.length + ' rows at row ' + (onlineLastRow + 1) + '.');

  // --- Offline: delete existing August rows (bottom-up, contiguous batches), then append fresh set ---
  var offlineValues = offlineSheet.getDataRange().getValues();
  var offlineHeader = offlineValues[0];
  var tsIdx = offlineHeader.indexOf('เวลาสั่งซื้อ');
  var augustRowNumbers = [];
  for (var j = 1; j < offlineValues.length; j++) {
    var d2 = parseThaiDateYearMonth_(offlineValues[j][tsIdx]);
    if (d2 && d2.year === 2026 && d2.month === 8) augustRowNumbers.push(j + 1);
  }

  if (augustRowNumbers.length > 0) {
    var descending = augustRowNumbers.slice().sort(function (a, b) { return b - a; });
    var ranges = [];
    var k = 0;
    while (k < descending.length) {
      var rangeEnd = descending[k];
      var rangeStart = rangeEnd;
      var m = k + 1;
      while (m < descending.length && descending[m] === rangeStart - 1) { rangeStart = descending[m]; m++; }
      ranges.push({ start: rangeStart, count: rangeEnd - rangeStart + 1 });
      k = m;
    }
    for (var r = 0; r < ranges.length; r++) {
      offlineSheet.deleteRows(ranges[r].start, ranges[r].count);
    }
    Logger.log('Offline: deleted ' + augustRowNumbers.length + ' existing August rows in ' + ranges.length + ' batch(es).');
  } else {
    Logger.log('Offline: no existing August rows found to delete.');
  }

  var offlineLastRow = offlineSheet.getLastRow();
  offlineSheet.getRange(offlineLastRow + 1, 1, OFFLINE_AUGUST_ROWS.length, OFFLINE_AUGUST_ROWS[0].length).setValues(OFFLINE_AUGUST_ROWS);
  Logger.log('Offline: inserted ' + OFFLINE_AUGUST_ROWS.length + ' fresh August rows at row ' + (offlineLastRow + 1) + '.');
  Logger.log('Done.');
}
